<div class="page-heading mb-4"><div><h1>Reports & Analytics</h1><p>Financial performance, collections and budget utilization at a glance.</p></div></div>
<div class="row g-3 mb-4"><?php foreach(array('Total sales'=>'sales','Total purchases'=>'purchases','Total expenses'=>'expenses','Collected sales'=>'paid_sales','Pending receivables'=>'pending_sales','Net position'=>'net') as $label=>$key): ?><div class="col-sm-6 col-xl-2"><div class="stat-card h-100"><div class="text-muted small mb-1"><?= $label ?></div><div class="fs-5 fw-bold">₹<?= number_format((float)($report[$key]??0),2) ?></div></div></div><?php endforeach; ?></div>
<div class="row g-4"><div class="col-xl-8"><div class="card"><div class="card-header">6-month financial trend</div><div class="card-body"><canvas id="financialChart" height="110"></canvas></div></div></div><div class="col-xl-4"><div class="card"><div class="card-header">Budget utilization</div><div class="card-body"><?php foreach($budgets as $b): $pct=$b['amount']>0?($b['spent']/$b['amount'])*100:0; ?><div class="mb-3"><div class="d-flex justify-content-between small mb-1"><span><?= html_escape($b['name']) ?></span><span><?= number_format($pct,0) ?>%</span></div><div class="progress"><div class="progress-bar <?= $pct>100?'bg-danger':'' ?>" style="width:<?= min(100,$pct) ?>%"></div></div><div class="small text-muted mt-1">₹<?= number_format((float)$b['spent'],2) ?> of ₹<?= number_format((float)$b['amount'],2) ?></div></div><?php endforeach; ?><?php if(!$budgets): ?><p class="text-muted mb-0">Budget analytics will appear after budgets are created.</p><?php endif; ?></div></div></div></div>
<script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.4/dist/chart.umd.min.js"></script>
<script>
document.addEventListener('DOMContentLoaded',function(){
 var canvas=document.getElementById('financialChart'); if(!canvas||typeof Chart==='undefined')return;
 new Chart(canvas,{type:'bar',data:{labels:<?= json_encode(array_column($monthly,'label')) ?>,datasets:[{label:'Sales',data:<?= json_encode(array_map('floatval',array_column($monthly,'sales'))) ?>},{label:'Purchases',data:<?= json_encode(array_map('floatval',array_column($monthly,'purchases'))) ?>},{label:'Expenses',data:<?= json_encode(array_map('floatval',array_column($monthly,'expenses'))) ?>}]},options:{responsive:true,plugins:{legend:{position:'bottom'}},scales:{y:{beginAtZero:true}}}});
});
</script>
